MODULE SPECNORM_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to SPECNORM
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPNORM_SHAPE(1)
  INTEGER(KIND=C_INT) :: IPSPEC_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKVSET_SHAPE(1)
  INTEGER(KIND=C_INT) :: IPMET_SHAPE(1)
END TYPE ARGS_INFO

END MODULE SPECNORM_ARGS_INFO_MOD

SUBROUTINE SPECNORM(PNORM, PSPEC, KVSET, KMASTER, KRESOL, PMET)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE SPECNORM_ARGS_INFO_MOD,      ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE SPECNORM_CPP_BINDING_SP(ARGS, KMASTER, KRESOL, PNORM, PSPEC, KVSET, PMET) &
  &  BIND(C, NAME="specnorm_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE SPECNORM_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KMASTER
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_FLOAT),            INTENT(OUT) :: PNORM(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PSPEC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSET(*)
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PMET(*)
END SUBROUTINE SPECNORM_CPP_BINDING_SP
SUBROUTINE SPECNORM_CPP_BINDING_DP(ARGS, KMASTER, KRESOL, PNORM, PSPEC, KVSET, PMET) &
  &  BIND(C, NAME="specnorm_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE SPECNORM_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KMASTER
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_DOUBLE),           INTENT(OUT) :: PNORM(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PSPEC(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KVSET(*)
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PMET(*)
END SUBROUTINE SPECNORM_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),              INTENT(OUT) :: PNORM(:)
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PSPEC(:,:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KVSET(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KMASTER
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PMET(:)

TYPE(ARGS_INFO) :: ARGS

TYPE(C_PTR) :: KMASTER_PTR, KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IMASTER, IRESOL

ARGS%IPNORM_SHAPE = SHAPE(PNORM, KIND=C_INT)
IF (PRESENT(PSPEC)) THEN
  ARGS%IPSPEC_SHAPE = SHAPE(PSPEC, KIND=C_INT)
ELSE
  ARGS%IPSPEC_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(KVSET)) THEN
  ARGS%IKVSET_SHAPE = SHAPE(KVSET, KIND=C_INT)
ELSE
  ARGS%IKVSET_SHAPE = 0_C_INT
ENDIF
IF (PRESENT(PMET)) THEN
  ARGS%IPMET_SHAPE = SHAPE(PMET, KIND=C_INT)
ELSE
  ARGS%IPMET_SHAPE = 0_C_INT
ENDIF

IF (PRESENT(KMASTER)) THEN
  IMASTER = KMASTER
  KMASTER_PTR = C_LOC(IMASTER)
ELSE
  KMASTER_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL SPECNORM_CPP_BINDING_SP(ARGS, KMASTER_PTR, KRESOL_PTR, PNORM, PSPEC=PSPEC, KVSET=KVSET, &
  &                          PMET=PMET)
#else
CALL SPECNORM_CPP_BINDING_DP(ARGS, KMASTER_PTR, KRESOL_PTR, PNORM, PSPEC=PSPEC, KVSET=KVSET, &
  &                          PMET=PMET)
#endif

END SUBROUTINE SPECNORM
